     "**ඔබ ඒවා එකට භාවිතා කළහොත් පමණක් කෙටිමං ස්වභාවික යැයි හැඟේ.** ස්පේස් (Space) මඟින් වාදනය සහ විරාම කරයි, Enter මඟින් වත්මන් පේළිය මුද්‍රා තබයි, Z මඟින් එක් පේළියක් අහෝසි කරයි — මූසිකය සහ යතුරුපුවරුව අතර මාරු වීම වෙනුවට ධාවනය අතරතුර කෙලින්ම Enter ඔබන්න.",
     "**ශ්‍රව්‍ය ගුණාත්මකභාවය නිරවද්‍යතාවයට බලපායි.** පැහැදිලි වාචික ශබ්ද සහිත මූලාශ්‍රයක් අනුගමනය කිරීම පහසුය; සජීවී පටිගත කිරීම් සහ ශබ්ද නඟා පසුබිම් සංගීතය ඇති මූලාශ්‍ර සැලකිය යුතු ලෙස අපහසුය."
